"""Review of AI logs for secrets, personal information, embedded memory and sensitive tool outputs.

Usage: log_scan.py HOOK_DIR OUT_TSV (FOLDER_DIR CLASS)...   or   log_scan.py HOOK_DIR OUT_TSV --inventory TSV
Writes one row per folder, file and category with a count. Prints category totals only: never log
contents, matched values, private terms, private-file names or memory text.
"""
import csv
import json
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path

REPO = Path("~/leveraged-etf-risk-analytics")
SRC = {"main-checkout": REPO, "worker-pipeline": REPO / ".claude/worktrees/worker-pipeline"}
MEMORY_DIR = Path.home() / ".claude/projects/-Users-[REDACTED:user]-leveraged-etf-risk-analytics/memory"
sys.path.insert(0, sys.argv[1])
import transcript_privacy as tp  # noqa: E402

OUT = sys.argv[2]
if sys.argv[3] == "--inventory":
    with open(sys.argv[4]) as fh:
        TARGETS = [(SRC[r["source"]] / "docs/ai-usage" / r["folder"], r["class"], r["source"]) for r in csv.DictReader(fh, delimiter="\t")]
else:
    args = sys.argv[3:]
    TARGETS = [(Path(args[i]), args[i + 1], "staged") for i in range(0, len(args), 2)]

red = tp.Redactor.for_project(REPO)
PRIVATE_LINES = red._private_lines
EXPECTED_ON_RERUN = {"model-reasoning"}  # sanitized thinking blocks are counted again; not a finding

PRIVATE_KEY = re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----")
JWT = re.compile(r"\beyJ[\w-]{10,}\.eyJ[\w-]{10,}\.[\w-]{10,}")
URL_CREDENTIAL = re.compile(r"\b[a-z][a-z0-9+.-]*://([^/\s:@'\"`]+):([^@\s/'\"`]+)@")
PHONE = re.compile(r"(?<![\d.])(?:\+?1[\s.-])?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}(?![\d.])")
APP = re.compile(r"/Applications/|[\w .-]+\.app/Contents")
HOME_ROOT = re.compile(r"(?<![\w/])~/([^/\s'\"`)\]]+)")
ENV_LINE = re.compile(r"^[A-Z_][A-Z0-9_]{2,}=")
PROJECT_ROOTS = {"leveraged-etf-risk-analytics", "etf-risk-backups", "etf-risk-investigations", "etf-risk-log-review"}
PERSONAL_ROOTS = {"Documents", "Desktop", "Downloads", "Pictures", "Movies", "Music", "Library", "Applications", ".ssh"}
CONTAINER_LISTING = re.compile(r"docker (?:compose[^|;&]* )?(?:ps|stats)\b")


def memory_lines():
    lines = set()
    for f in MEMORY_DIR.glob("*.md"):
        text = f.read_text(encoding="utf-8")
        if text.startswith("---"):
            text = text.split("---", 2)[-1]
        for line in text.splitlines():
            line = line.strip().lstrip("-*").strip()
            if len(line) >= 30 and re.search(r"[A-Za-z]{4}", line):
                lines.add(line)
    return lines


MEMORY = memory_lines()
_committed_passwords = {}


def committed(value):
    """True if the value appears in a file tracked in origin/main (a test or placeholder credential)."""
    if value not in _committed_passwords:
        r = subprocess.run(["git", "-C", str(REPO), "grep", "-q", "-F", "-e", value, "origin/main", "--", ":!docs/ai-usage"])
        _committed_passwords[value] = r.returncode == 0
    return _committed_passwords[value]


def strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, list):
        for v in obj:
            yield from strings(v)
    elif isinstance(obj, dict):
        for k, v in obj.items():
            yield k
            yield from strings(v)


def tool_blocks(records):
    """(command or file path, result text) pairs for tool calls, matched by tool_use_id."""
    uses, results = {}, {}
    for rec in records:
        content = rec.get("message", {}).get("content") if isinstance(rec.get("message"), dict) else None
        for b in content if isinstance(content, list) else []:
            if not isinstance(b, dict):
                continue
            if b.get("type") == "tool_use":
                inp = b.get("input") or {}
                uses[b.get("id")] = " ".join(str(inp.get(k, "")) for k in ("command", "file_path", "path", "pattern"))
            elif b.get("type") == "tool_result":
                results[b.get("tool_use_id")] = "\n".join(strings(b.get("content")))
    return [(cmd, results.get(i, "")) for i, cmd in uses.items()]


def scan_text_values(values, c):
    """Checks that apply to decoded text, from either format."""
    for s in values:
        for name, plines in PRIVATE_LINES.items():
            hit = len(plines.intersection(map(tp._normalize_line, s.splitlines())))
            if 1 <= hit < tp.MIN_FILE_LINE_MATCHES:
                c["private-file lines below the threshold"] += hit
        c["secret: private key"] += len(PRIVATE_KEY.findall(s))
        c["secret: JWT"] += len(JWT.findall(s))
        for user, password in URL_CREDENTIAL.findall(s):
            if password.startswith(("$", "{", "<", "[REDACTED")) or password in {"password", "pass", "PASSWORD"}:
                continue
            c["URL credential (committed test value)" if committed(password) else "secret: URL credential not in the repo"] += 1
        c["tool output: app name or path"] += len(APP.findall(s))
        for root in HOME_ROOT.findall(s):
            if root in PROJECT_ROOTS or root.startswith((".claude", "etf-risk")):
                continue
            c["path outside the project: personal folder" if root in PERSONAL_ROOTS else "path outside the project: other"] += 1
[REDACTED:memory]
        c["[REDACTED:memory] markers (already sanitized)"] += s.count("[REDACTED:memory]")
    joined = "\n".join(values)
    c["memory: content lines"] += sum(1 for line in MEMORY if line in joined)


def scan_jsonl(path, c):
    records = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
    red.counts = tp.Counter() if hasattr(tp, "Counter") else Counter()
    for rec in records:
        red.record(rec)
    for k, v in red.counts.items():
        if k not in EXPECTED_ON_RERUN:
            c[f"missed by the hook then, caught now: {k}"] += v
    for rec in records:
        if rec.get("type") == "user" and not rec.get("isMeta"):
            content = rec.get("message", {}).get("content") if isinstance(rec.get("message"), dict) else None
            if isinstance(content, str):
                c["personal: phone-like number in a prompt"] += len(PHONE.findall(content))
    for cmd, result in tool_blocks(records):
        if "/memory/" in cmd and ".claude/projects" in cmd:
            c["memory: tool call on a memory file"] += 1
        if ".git/info/exclude" in cmd:
            c["tool output: .git/info/exclude access"] += 1
        if CONTAINER_LISTING.search(cmd):
            for line in result.splitlines()[1:]:
                name = line.split()[-1] if line.split() else ""
                if re.fullmatch(r"[a-z0-9][\w.-]+", name) and not name.startswith("etf-risk-jobs") and name != "NAMES":
                    c["tool output: other project's container"] += 1
        run = 0
        for line in result.splitlines():
            run = run + 1 if ENV_LINE.match(line) else 0
            if run == 5:
                c["tool output: environment dump"] += 1
    scan_text_values(list(strings(records)), c)


def scan_md(path, c):
    text = path.read_text(encoding="utf-8")
    red.counts = Counter()
    for section in re.split(r"\n(?=## \d+\. )", text):
        red.text(section)
    for k, v in red.counts.items():
        if k not in EXPECTED_ON_RERUN:
            c[f"missed by the hook then, caught now: {k}"] += v
    scan_text_values([text], c)


rows, totals = [], defaultdict(lambda: [0, 0])
for folder, cls, source in TARGETS:
    for name, fn in (("transcript.jsonl", scan_jsonl), ("transcript.md", scan_md)):
        p = folder / name
        if not p.is_file():
            continue
        c = Counter()
        fn(p, c)
        for cat, n in c.items():
            if n:
                rows.append({"source": source, "folder": folder.name, "class": cls, "file": name, "category": cat, "count": n})
                totals[(cls.split(":")[0], cat)][1] += n
    for cat in {r["category"] for r in rows if r["folder"] == folder.name and r["source"] == source}:
        totals[(cls.split(":")[0], cat)][0] += 1

with open(OUT, "w", newline="") as fh:
    w = csv.DictWriter(fh, fieldnames=["source", "folder", "class", "file", "category", "count"], delimiter="\t")
    w.writeheader()
    w.writerows(rows)
print(f"scanned {len(TARGETS)} folders; {len(MEMORY)} memory lines and {sum(len(v) for v in PRIVATE_LINES.values())} private-file lines used as references")
for (group, cat), (folders, n) in sorted(totals.items()):
    print(f"{group} | {cat} | {folders} folders | {n}")

