"""Characterise the remaining tool-output and private-file findings without printing values.

Usage: log_diag2.py HOOK_DIR FINDINGS_TSV MAIN_ROOT
"""
import csv
import json
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path

sys.path.insert(0, sys.argv[1])
import transcript_privacy as tp  # noqa: E402

REPO = Path("~/leveraged-etf-risk-analytics")
ROOTS = {"main-checkout": REPO / "docs/ai-usage", "worker-pipeline": REPO / ".claude/worktrees/worker-pipeline/docs/ai-usage"}
MAIN_ROOT = Path(sys.argv[3])
red = tp.Redactor.for_project(REPO)
SERVICES = {"mysql", "kafka", "redis", "zookeeper", "spark", "jobs", "etf", "risk"}
CONTAINER_LISTING = re.compile(r"docker (?:compose[^|;&]* )?(?:ps|stats)\b")
APP = re.compile(r"/Applications/([^/\n\"]+?)\.app|([\w .-]+)\.app/Contents")
HOME_ROOT = re.compile(r"(?<![\w/])~/([^/\s'\"`)\]]+)")
SKIP_ROOTS = {"leveraged-etf-risk-analytics", "Documents", "Desktop", "Downloads", "Pictures", "Movies", "Music", "Library", "Applications", ".ssh"}


def committed(value):
    return subprocess.run(["git", "-C", str(REPO), "grep", "-q", "-F", "-e", value, "origin/main", "--", ":!docs/ai-usage"]).returncode == 0


def strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, list):
        for v in obj:
            yield from strings(v)
    elif isinstance(obj, dict):
        for v in obj.values():
            yield from strings(v)


wanted = defaultdict(set)
with open(sys.argv[2]) as fh:
    for r in csv.DictReader(fh, delimiter="\t"):
        wanted[(r["source"], r["folder"], r["class"])].add(r["category"])

out = defaultdict(Counter)
rows = []
for (source, folder, cls), cats in sorted(wanted.items()):
    root = ROOTS.get(source, MAIN_ROOT)
    path = root / folder / "transcript.jsonl"
    if not path.is_file():
        continue
    records = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
    text = "\n".join(s for r in records for s in strings(r))
    group = cls.split(":")[0]
    c = Counter()
    if "container: OTHER project's name" in cats:
        uses = {}
        for r in records:
            msg = r.get("message") if isinstance(r.get("message"), dict) else {}
            for b in msg.get("content") if isinstance(msg.get("content"), list) else []:
                if isinstance(b, dict) and b.get("type") == "tool_use":
                    uses[b.get("id")] = str((b.get("input") or {}).get("command", ""))
        names = set()
        for r in records:
            msg = r.get("message") if isinstance(r.get("message"), dict) else {}
            for b in msg.get("content") if isinstance(msg.get("content"), list) else []:
                if isinstance(b, dict) and b.get("type") == "tool_result" and CONTAINER_LISTING.search(uses.get(b.get("tool_use_id"), "")):
                    res = "\n".join(strings(b.get("content")))
                    names |= set(re.findall(r"(?<![\w.-])([a-z0-9][a-z0-9_.-]*[a-z][a-z0-9_.-]*[-_]\d+)(?![\w.-])", res))
        for n in names:
            if n.startswith("etf-risk-jobs") or (n.startswith(("docker-", "docker_")) and set(re.split(r"[-_]", n)) & SERVICES):
                continue
            parts = set(re.split(r"[-_.]", n))
            kind = "names a service of this stack" if parts & SERVICES else "no link to this project"
            c[f"distinct container name, {kind}"] += 1
    if any(k.startswith("private-file line below the threshold, NOT") for k in cats):
        for name, plines in red._private_lines.items():
            for line in plines:
                if line in text and not committed(line):
                    shape = ("heading" if line.startswith("#") else "table row" if line.startswith("|") else
                             "list item" if line[:2] in ("- ", "* ") or re.match(r"\d+\.", line) else "prose")
                    c[f"private-file line not in the repo: {shape}, {len(line)} chars"] += 1
    if "tool output: .git/info/exclude access" in cats:
        c["exclude-file mentions in tool calls"] += sum(1 for r in records for s in strings(r) if ".git/info/exclude" in s and len(s) < 2000)
    if any(k.startswith("app path: OTHER") for k in cats):
        apps = {(a or b).strip() for a, b in APP.findall(text)} - {""}
        c["distinct apps other than Docker"] += len({a for a in apps if "Docker" not in a})
    if "home path: OTHER folder (may name another project)" in cats:
        roots = {r for r in HOME_ROOT.findall(text) if r not in SKIP_ROOTS and not r.startswith((".", "etf-risk"))}
        c["distinct non-project home folders"] += len(roots)
    for k, v in c.items():
        out[group][k] += v
        rows.append((source, folder, cls, k, v))

with open(Path(sys.argv[2]).with_suffix(".diag2.tsv"), "w") as fh:
    fh.write("source\tfolder\tclass\tdetail\tcount\n")
    for row in rows:
        fh.write("\t".join(map(str, row)) + "\n")
for group, c in out.items():
    print(f"== {group}")
    for k, v in sorted(c.items()):
        print(f"  {v:4d}  {k}  ({len({r[1] for r in rows if r[2].split(':')[0] == group and r[3] == k})} folders)")

