    """In tool output, replace only the lines that carry memory text; keep the rest of the output."""
    if isinstance(obj, str):
        if key in KEEP_KEYS or not has_memory(obj):
            return obj
        out = []
        for line in obj.split("\n"):
            if has_memory(line):
                self.count += 1
                out.append(MARK)
            else:
                out.append(line)
        return "\n".join(out)
    if isinstance(obj, list):
        return [self.lines(v, key) for v in obj]
    if isinstance(obj, dict):
        return {k: self.lines(v, k) for k, v in obj.items()}
    return obj

def record(self, rec, memory_ids):
    rec = self._record(rec, memory_ids)
    if rec.get("type") in ("user", "assistant"):
        # Tool results and fields beside the message (e.g. toolUseResult) that quote memory text.
        msg = rec.get("message")
        if isinstance(msg, dict) and isinstance(msg.get("content"), list):
            rec["message"] = {**msg, "content": [
                {**b, "content": self.lines(b.get("content"))} if isinstance(b, dict) and b.get("type") == "tool_result" else b
                for b in msg["content"]]}
        for k in [k for k in rec if k not in ("message", *KEEP_KEYS)]:
            rec[k] = self.lines(rec[k], k)
    return rec

def _record(self, rec, memory_ids):

