"""Stage sanitized copies of AI-log folders: memory content replaced as in e7aea41, Markdown re-rendered.

Usage: sanitize_candidates.py HOOK_DIR SOURCE_LOG_DIR STAGE_DIR FOLDER...
Reads each folder's redacted transcript.jsonl (never the raw file), replaces memory content with
[REDACTED:memory], keeps paths and file names, and writes transcript.jsonl and transcript.md to the stage.
Sources are never written. Prints counts only.
"""
import json
import re
import sys
from collections import Counter
from datetime import datetime
from pathlib import Path

sys.path.insert(0, sys.argv[1])
from save_transcript import render_markdown  # noqa: E402

SOURCE, STAGE = Path(sys.argv[2]), Path(sys.argv[3])
MEMORY_DIR = Path.home() / ".claude/projects/-Users-[REDACTED:user]-leveraged-etf-risk-analytics/memory"
MARK = "[REDACTED:memory]"
[REDACTED:memory]
KEEP_KEYS = {"file_path", "filePath", "path", "type", "id", "tool_use_id", "name", "uuid", "parentUuid", "timestamp", "sessionId"}
SECTION = re.compile(r"(Contents of [^\n]*?/memory/[^\n]*?:)\n.*?(?=\n\s*Contents of |</system-reminder>|\Z)", re.S)


def memory_lines():
    out = set()
    for f in MEMORY_DIR.glob("*.md"):
        t = f.read_text(encoding="utf-8")
        for line in (t.split("---", 2)[-1] if t.startswith("---") else t).splitlines():
            line = line.strip().lstrip("-*").strip()
            if len(line) >= 30 and re.search(r"[A-Za-z]{4}", line):
                out.add(line)
    return out


MEMORY = memory_lines()


def is_memory_path(s):
    return ".claude/projects" in s and "/memory/" in s


def has_memory(s):
    return HEADER in s or any(line in s for line in MEMORY)


class Sanitizer:
    def __init__(self):
        self.count = 0

    def wipe(self, obj, key=None):
        """Replace every string except identifiers and paths."""
        if isinstance(obj, str):
            if key in KEEP_KEYS or obj == MARK:
                return obj
            self.count += 1
            return MARK
        if isinstance(obj, list):
            return [self.wipe(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.wipe(v, k) for k, v in obj.items()}
        return obj

    def scrub(self, obj, key=None):
        """Replace embedded memory sections or strings carrying memory content; leave the rest."""
        if isinstance(obj, str):
            if key in KEEP_KEYS:
                return obj
            if SECTION.search(obj):
                new, n = SECTION.subn(lambda m: m.group(1) + " " + MARK, obj)
                self.count += n
                obj = new
            if has_memory(obj):
                self.count += 1
                return MARK
            return obj
        if isinstance(obj, list):
            return [self.scrub(v, key) for v in obj]
        if isinstance(obj, dict):
            return {k: self.scrub(v, k) for k, v in obj.items()}
        return obj

    def record(self, rec, memory_ids):
        t = rec.get("type")
        if t not in ("user", "assistant"):
            return self.scrub(rec)  # attachments, API-request and other context records
        rec = dict(rec)
        msg = rec.get("message")
        if isinstance(msg, dict) and isinstance(msg.get("content"), list):
            blocks = []
            for b in msg["content"]:
                if isinstance(b, dict) and b.get("type") == "tool_use" and b.get("id") in memory_ids:
                    b = {**b, "input": {k: (v if k in KEEP_KEYS else self.wipe(v, k)) for k, v in (b.get("input") or {}).items()}}
                elif isinstance(b, dict) and b.get("type") == "tool_result" and b.get("tool_use_id") in memory_ids:
                    b = {**b, "content": self.wipe(b.get("content"))}
                elif isinstance(b, dict) and b.get("type") == "text" and "<system-reminder>" in b.get("text", ""):
                    b = self.scrub(b)
                blocks.append(b)
            rec["message"] = {**msg, "content": blocks}
            used = {b.get("tool_use_id") for b in msg["content"] if isinstance(b, dict)}
            if used & memory_ids and "toolUseResult" in rec:
                rec["toolUseResult"] = self.wipe(rec["toolUseResult"])
        elif isinstance(msg, dict) and isinstance(msg.get("content"), str) and ("<system-reminder>" in msg["content"] or rec.get("isMeta")):
            rec["message"] = {**msg, "content": self.scrub(msg["content"])}
        return rec


def header_counts(md):
    m = re.search(r"Redactions \(.*?\): (.*?)\. Rules:", md)
    c = Counter()
    if m and m.group(1) != "none":
        for part in m.group(1).split(", "):
            k, v = part.rsplit(" ×", 1)
            c[k] = int(v)
    return c


total = Counter()
for folder in sys.argv[4:]:
    src = SOURCE / folder
    records = [json.loads(line) for line in (src / "transcript.jsonl").read_text(encoding="utf-8").splitlines() if line.strip()]
    ids = set()
    for rec in records:
        msg = rec.get("message") if isinstance(rec.get("message"), dict) else {}
        for b in msg.get("content") if isinstance(msg.get("content"), list) else []:
            if isinstance(b, dict) and b.get("type") == "tool_use" and is_memory_path(json.dumps(b.get("input") or {})):
                ids.add(b.get("id"))
    s = Sanitizer()
    clean = [s.record(r, ids) for r in records]
    jsonl = "\n".join(json.dumps(r, ensure_ascii=False) for r in clean) + "\n"
    md_old = (src / "transcript.md").read_text(encoding="utf-8")
    session = re.search(r"Session: `([^`]+)`", md_old).group(1)
    sent = datetime.strptime(re.search(r"prompt sent (\d{4}-\d{2}-\d{2} \d{2}:\d{2})", md_old).group(1), "%Y-%m-%d %H:%M")
    number = int(folder.rsplit("-", 1)[1])
    counts = header_counts(md_old)
    if s.count:
        counts["memory"] += s.count
    out = STAGE / folder
    out.mkdir(parents=True, exist_ok=True)
    (out / "transcript.jsonl").write_text(jsonl, encoding="utf-8")
    (out / "transcript.md").write_text(render_markdown(jsonl, session, number, sent, counts), encoding="utf-8")
    assert len(clean) == len(records)
    total["folders"] += 1
    total["memory items replaced"] += s.count
    print(f"{folder}: records {len(records)}, memory tool calls {len(ids)}, memory items replaced {s.count}")
print(dict(total))

