import csv, json, re, subprocess, sys
from collections import Counter
from pathlib import Path
S = Path(sys.argv[1]); MAIN = S / "main-logs/docs/ai-usage"
LIST = re.compile(r"docker (?:compose[^|;&]* )?(?:ps|stats)\b")
def committed(v): return subprocess.run(["git", "grep", "-q", "-F", "-e", v, "origin/main", "--", ":!docs/ai-usage"]).returncode == 0
def strings(o):
    if isinstance(o, str): yield o
    elif isinstance(o, list):
        for v in o: yield from strings(v)
    elif isinstance(o, dict):
        for v in o.values(): yield from strings(v)
folders = sorted({r["folder"] for r in csv.DictReader(open(S / "main_findings.tsv"), delimiter="\t") if r["category"] in ("container: OTHER project's name", "tool output: .git/info/exclude access")})
for f in folders:
    recs = [json.loads(l) for l in (MAIN / f / "transcript.jsonl").read_text().splitlines() if l.strip()]
    uses, c = {}, Counter()
    for r in recs:
        m = r.get("message") if isinstance(r.get("message"), dict) else {}
        for b in m.get("content") if isinstance(m.get("content"), list) else []:
            if not isinstance(b, dict): continue
            if b.get("type") == "tool_use": uses[b.get("id")] = json.dumps(b.get("input") or {})
            elif b.get("type") == "tool_result":
                cmd, res = uses.get(b.get("tool_use_id"), ""), "\n".join(strings(b.get("content")))
                if LIST.search(cmd):
                    for line in res.splitlines()[1:]:
                        p = line.split()
                        for n in ({p[-1]} if p else set()) | ({p[1]} if "stats" in cmd and len(p) > 1 else set()):
                            if re.fullmatch(r"[a-z0-9][\w.-]*[a-z][\w.-]*", n) and not n.startswith(("etf-risk-jobs", "docker")) and n not in ("NAMES", "NAME") and not committed(n):
                                c["other container name in a NAMES column"] += 1
                if ".git/info/exclude" in cmd and re.search(r"(cat|head|tail|sed -n|less)\s[^|;]*\.git/info/exclude|file_path\": \"[^\"]*\.git/info/exclude", cmd):
                    c["direct read of .git/info/exclude, result lines"] += len([l for l in res.splitlines() if l.strip()])
    if c: print(f"{f}: " + "; ".join(f"{k} {v}" for k, v in sorted(c.items())))
